/**
 * In order to tell the service-worker to perform a task, we send a message using
 * navigator.serviceWorker.controller?.postMessage() and the message needs to be
 * of type ServiceWorkerMessage.  The type property is how the service-worker responds
 * to the message.
 *
 * You can see which types that have support by looking at handleMfeUtilsServiceWorkerMessages()
 * in service-worker-utils.ts
 */
export interface ServiceWorkerMessage {
    type: string;
}
